import apartmentImage from "@/assets/frameflow-apartment.jpg";
import studioImage from "@/assets/frameflow-studio.jpg";
import rooftopImage from "@/assets/frameflow-rooftop.jpg";
import mayaImage from "@/assets/frameflow-maya.jpg";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "FRAMEFLOW — Production Intelligence" },
      { name: "description", content: "Build consistent production worlds, plan shots, and validate visual continuity with FRAMEFLOW." },
      { property: "og:title", content: "FRAMEFLOW — Production Intelligence" },
      { property: "og:description", content: "Build consistent production worlds, plan shots, and validate visual continuity with FRAMEFLOW." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: Frameflow,
});

type View = "overview" | "projects" | "project" | "assets" | "characters" | "character" | "locations" | "location" | "rooms" | "props" | "prop" | "stories" | "story" | "scenes" | "scene" | "shots" | "shot" | "storyboard" | "continuity" | "issue" | "relationships" | "history";
type ImageSrc = string;

const projects = [
  { name: "Home Film POC", status: "In production", image: apartmentImage, stats: ["3 locations", "2 characters", "24 scenes", "84 shots"], updated: "Edited 12 min ago" },
  { name: "Midnight Apartment", status: "Reference review", image: studioImage, stats: ["2 locations", "4 characters", "12 scenes", "46 shots"], updated: "Edited yesterday" },
  { name: "The Last Frame", status: "Story development", image: rooftopImage, stats: ["5 locations", "3 characters", "18 scenes", "62 shots"], updated: "Edited 3 days ago" },
];

const assets = [
  { name: "Maya", type: "Character", refs: "12 references", status: "Identity verified", image: mayaImage, view: "character" as View },
  { name: "Apartment", type: "Location", refs: "18 references", status: "Production-ready", image: apartmentImage, view: "location" as View },
  { name: "Creative Studio", type: "Location", refs: "9 references", status: "Analyzed", image: studioImage, view: "location" as View },
  { name: "Rooftop", type: "Location", refs: "7 references", status: "Production-ready", image: rooftopImage, view: "location" as View },
  { name: "Phone", type: "Prop", refs: "6 references", status: "State tracked", image: apartmentImage, view: "prop" as View },
  { name: "Camera", type: "Prop", refs: "4 references", status: "Confirmed", image: studioImage, view: "prop" as View },
  { name: "Coffee Cup", type: "Prop", refs: "3 references", status: "State tracked", image: apartmentImage, view: "prop" as View },
  { name: "Daniel", type: "Character", refs: "8 references", status: "Identity review", image: rooftopImage, view: "character" as View },
];

const shots = [
  { number: "01", type: "Extreme wide", copy: "Establish the apartment at blue hour", image: apartmentImage, status: "Approved" },
  { number: "02", type: "Wide", copy: "Maya enters from the window", image: studioImage, status: "Approved" },
  { number: "03", type: "Medium", copy: "She finds the phone on the desk", image: rooftopImage, status: "Review" },
  { number: "04", type: "Close-up", copy: "A message changes the room", image: mayaImage, status: "Draft" },
  { number: "05", type: "Over the shoulder", copy: "The screen catches the window light", image: apartmentImage, status: "Draft" },
  { number: "06", type: "Two shot", copy: "Daniel appears in the doorway", image: studioImage, status: "Draft" },
];

const navGroups = [
  { label: "Workspace", items: [{ label: "Overview", icon: Compass, view: "overview" as View }, { label: "Projects", icon: FolderOpen, view: "projects" as View }] },
  { label: "Production", items: [{ label: "Stories", icon: Lightbulb, view: "stories" as View }, { label: "Scenes", icon: Clapperboard, view: "scenes" as View }, { label: "Shots", icon: Target, view: "shots" as View }, { label: "Storyboard", icon: Film, view: "storyboard" as View }] },
  { label: "Assets", items: [{ label: "All Assets", icon: Layers3, view: "assets" as View }, { label: "Characters", icon: Users, view: "characters" as View }, { label: "Locations", icon: MapPin, view: "locations" as View }, { label: "Rooms", icon: Box, view: "rooms" as View }, { label: "Props", icon: Archive, view: "props" as View }] },
  { label: "Intelligence", items: [{ label: "Production AI", icon: Sparkles, view: "overview" as View, ai: true }, { label: "Continuity", icon: CircleDot, view: "continuity" as View }, { label: "Relationships", icon: Link2, view: "relationships" as View }, { label: "History", icon: History, view: "history" as View }] },
];

function Frameflow() {
  const [view, setView] = useState<View>("overview");
  const [collapsed, setCollapsed] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [assetOpen, setAssetOpen] = useState(false);
  const [processing, setProcessing] = useState<string | null>(null);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); }
      if (event.key === "Escape") { setCommandOpen(false); setAiOpen(false); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const go = (next: View) => { setView(next); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const runProcess = (label: string, next?: View) => {
    setProcessing(label);
    window.setTimeout(() => { setProcessing(null); toast.success(`${label} complete`, { description: "The production context is ready for review." }); if (next) go(next); }, 1400);
  };

  return (
    <div className="min-h-screen bg-background text-foreground">
      <Toaster position="bottom-right" />
      <div className="flex min-h-screen">
        <Sidebar collapsed={collapsed} setCollapsed={setCollapsed} view={view} go={go} onCreate={() => setCreateOpen(true)} />
        <main className="min-w-0 flex-1">
          <Topbar view={view} go={go} onCommand={() => setCommandOpen(true)} onAI={() => setAiOpen(true)} />
          <div className="frameflow-scrollbar h-[calc(100vh-64px)] overflow-y-auto">
            <div className="mx-auto max-w-[1500px] px-6 py-8 lg:px-10">
              {view === "overview" && <Overview go={go} onCreate={() => setCreateOpen(true)} onAI={() => setAiOpen(true)} />}
              {view === "projects" && <Projects go={go} onCreate={() => setCreateOpen(true)} />}
              {view === "project" && <ProjectOverview go={go} onAI={() => setAiOpen(true)} />}
              {view === "assets" && <AssetLibrary go={go} onCreate={() => setAssetOpen(true)} />}
              {view === "characters" && <AssetList title="Characters" eyebrow="Production identities" description="People, performance states and identity references across your stories." items={assets.filter((a) => a.type === "Character")} go={go} />}
              {view === "character" && <CharacterDetail go={go} onProcess={runProcess} />}
              {view === "locations" && <AssetList title="Locations" eyebrow="Production world" description="Physical spaces that hold your stories together." items={assets.filter((a) => a.type === "Location")} go={go} />}
              {view === "location" && <LocationDetail go={go} />}
              {view === "rooms" && <RoomView go={go} />}
              {view === "props" && <AssetList title="Props" eyebrow="Objects that matter" description="Track the things that move, change and carry meaning through each scene." items={assets.filter((a) => a.type === "Prop")} go={go} />}
              {view === "prop" && <PropDetail go={go} />}
              {view === "stories" && <Stories go={go} onCreate={() => toast.success("Story composer ready", { description: "Describe a sequence and FRAMEFLOW will structure it." })} />}
              {view === "story" && <StoryDetail go={go} onProcess={runProcess} />}
              {view === "scenes" && <Scenes go={go} onProcess={runProcess} />}
              {view === "scene" && <SceneDetail go={go} onProcess={runProcess} />}
              {view === "shots" && <Shots go={go} onProcess={runProcess} />}
              {view === "shot" && <ShotDetail go={go} onProcess={runProcess} />}
              {view === "storyboard" && <Storyboard go={go} />}
              {view === "continuity" && <Continuity go={go} onProcess={runProcess} />}
              {view === "issue" && <ContinuityIssue go={go} onProcess={runProcess} />}
              {view === "relationships" && <Relationships go={go} />}
              {view === "history" && <HistoryView />}
            </div>
          </div>
        </main>
        {aiOpen && <ProductionAI close={() => setAiOpen(false)} go={go} />}
      </div>
      {processing && <ProcessingOverlay label={processing} />}
      <CommandPalette open={commandOpen} close={() => setCommandOpen(false)} go={(next) => { setCommandOpen(false); go(next); }} onCreate={() => { setCommandOpen(false); setCreateOpen(true); }} />
      <CreateProject open={createOpen} close={() => setCreateOpen(false)} go={go} />
      <CreateAsset open={assetOpen} close={() => setAssetOpen(false)} go={go} />
    </div>
  );
}

function Sidebar({ collapsed, setCollapsed, view, go, onCreate }: { collapsed: boolean; setCollapsed: (value: boolean) => void; view: View; go: (view: View) => void; onCreate: () => void }) {
  return <aside className={`${collapsed ? "w-[72px]" : "w-[236px]"} hidden shrink-0 border-r border-border bg-sidebar transition-[width] duration-200 lg:block`}>
    <div className="sticky top-0 flex h-screen flex-col px-3 py-4">
      <div className={`mb-6 flex items-center ${collapsed ? "justify-center" : "justify-between px-2"}`}>
        {!collapsed && <button className="flex items-center gap-2.5 text-left" onClick={() => go("overview")} aria-label="Go to FRAMEFLOW overview"><span className="grid h-7 w-7 place-items-center rounded-lg bg-foreground text-background"><Film className="h-4 w-4" /></span><span className="text-[17px] font-bold tracking-[-0.04em]">FRAMEFLOW</span></button>}
        {collapsed && <button onClick={() => go("overview")} className="grid h-8 w-8 place-items-center rounded-lg bg-foreground text-background" aria-label="Go to overview"><Film className="h-4 w-4" /></button>}
        {!collapsed && <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground" onClick={() => setCollapsed(true)} aria-label="Collapse sidebar"><PanelLeftClose className="h-4 w-4" /></Button>}
      </div>
      {collapsed && <Button variant="ghost" size="icon" className="mb-5 h-9 w-full text-muted-foreground" onClick={() => setCollapsed(false)} aria-label="Expand sidebar"><PanelLeftOpen className="h-4 w-4" /></Button>}
      <Button onClick={onCreate} className={`mb-6 h-10 bg-cyan text-primary-foreground hover:bg-cyan-strong ${collapsed ? "px-0" : "justify-between px-3"}`}><span className="flex items-center gap-2"><Plus className="h-4 w-4" />{!collapsed && "New project"}</span>{!collapsed && <span className="text-primary-foreground/70">⌘ N</span>}</Button>
      <nav className="frameflow-scrollbar flex-1 space-y-5 overflow-y-auto">
        {navGroups.map((group) => <div key={group.label}><div className={`mb-2 px-2 text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground ${collapsed ? "text-center" : ""}`}>{collapsed ? "·" : group.label}</div><div className="space-y-0.5">{group.items.map((item) => <button key={item.label} onClick={() => item.ai ? undefined : go(item.view)} className={`group flex w-full items-center gap-3 rounded-lg px-2.5 py-2 text-left text-[13px] font-medium transition-colors ${view === item.view || (item.label === "Production AI" && false) ? "bg-cyan-soft text-cyan-strong" : "text-muted-foreground hover:bg-accent hover:text-foreground"} ${collapsed ? "justify-center px-0" : ""}`} title={collapsed ? item.label : undefined}><item.icon className={`h-[17px] w-[17px] shrink-0 ${item.ai ? "text-cyan" : ""}`} />{!collapsed && <span>{item.label}</span>}{!collapsed && item.ai && <span className="ml-auto rounded-full bg-cyan-soft px-1.5 py-0.5 text-[9px] font-bold text-cyan-strong">AI</span>}</button>)}</div></div>)}
      </nav>
      {!collapsed && <div className="mt-5 border-t border-border pt-4"><button className="flex w-full items-center gap-3 rounded-lg px-2 py-2 text-left hover:bg-accent"><span className="grid h-8 w-8 place-items-center rounded-full bg-foreground text-xs font-semibold text-background">GK</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">Girish Kadambari</span><span className="block text-[11px] text-muted-foreground">Director workspace</span></span><MoreHorizontal className="h-4 w-4 text-muted-foreground" /></button></div>}
    </div>
  </aside>;
}

function Topbar({ view, go, onCommand, onAI }: { view: View; go: (view: View) => void; onCommand: () => void; onAI: () => void }) {
  const labels: Record<View, string> = { overview: "Overview", projects: "Projects", project: "Home Film POC", assets: "Assets", characters: "Characters", character: "Maya", locations: "Locations", location: "Apartment", rooms: "Rooms", props: "Props", prop: "Phone", stories: "Stories", story: "The Last Frame", scenes: "Scenes", scene: "Scene 04", shots: "Shots", shot: "Shot 04", storyboard: "Storyboard", continuity: "Continuity", issue: "Issue review", relationships: "Relationships", history: "History" };
  return <header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-border bg-background/95 px-6 backdrop-blur lg:px-10"><div className="flex min-w-0 items-center gap-2 text-xs text-muted-foreground"><Button variant="ghost" size="icon" className="mr-1 h-8 w-8 lg:hidden" aria-label="Open navigation"><Menu className="h-4 w-4" /></Button><button onClick={() => go("overview")} className="hidden hover:text-foreground sm:block">Home</button><ChevronRight className="hidden h-3.5 w-3.5 sm:block" /><span className="truncate font-medium text-foreground">{labels[view]}</span>{view !== "overview" && <><ChevronRight className="h-3.5 w-3.5" /><span className="hidden text-muted-foreground sm:block">Production context</span></>}</div><div className="flex items-center gap-2"><button onClick={onCommand} className="hidden h-9 w-52 items-center gap-2 rounded-lg border border-border bg-card px-3 text-left text-xs text-muted-foreground shadow-sm transition-colors hover:border-cyan/40 hover:text-foreground md:flex"><Search className="h-3.5 w-3.5" /><span className="flex-1">Search production…</span><kbd className="rounded border border-border bg-muted px-1.5 py-0.5 text-[10px]">⌘K</kbd></button><Button variant="ghost" size="icon" className="h-9 w-9" onClick={onCommand} aria-label="Search"><Search className="h-4 w-4" /></Button><Button variant="ghost" size="icon" className="h-9 w-9 text-cyan-strong" onClick={onAI} aria-label="Open Production AI"><Sparkles className="h-4 w-4" /></Button><Button variant="ghost" size="icon" className="relative h-9 w-9" aria-label="Notifications"><Bell className="h-4 w-4" /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-cyan" /></Button><span className="ml-1 grid h-8 w-8 place-items-center rounded-full bg-foreground text-[10px] font-semibold text-background">GK</span></div></header>;
}

function PageHeader({ eyebrow, title, description, action, secondary }: { eyebrow?: string; title: string; description?: string; action?: ReactNode; secondary?: ReactNode }) {
  return <div className="mb-9 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="mb-2 flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-cyan-strong">{eyebrow && <><span className="h-1.5 w-1.5 rounded-full bg-cyan" />{eyebrow}</>}</div><h1 className="text-3xl font-bold tracking-[-0.045em] sm:text-[40px]">{title}</h1>{description && <p className="mt-2 max-w-xl text-[15px] leading-6 text-muted-foreground">{description}</p>}</div><div className="flex items-center gap-2">{secondary}{action}</div></div>;
}

function Overview({ go, onCreate, onAI }: { go: (view: View) => void; onCreate: () => void; onAI: () => void }) {
  return <div><section className="relative mb-10 overflow-hidden rounded-2xl border border-border bg-card"><div className="grid min-h-[286px] items-end md:grid-cols-[1.15fr_0.85fr]"><div className="relative z-10 px-7 py-8 sm:px-10 sm:py-10"><div className="mb-5 flex items-center gap-2 text-xs font-medium text-cyan-strong"><span className="h-2 w-2 rounded-full bg-cyan ai-pulse" />Production intelligence online</div><h1 className="max-w-xl text-4xl font-bold leading-[1.02] tracking-[-0.06em] sm:text-6xl">Build your<br /><span className="text-cyan-strong">production world.</span></h1><p className="mt-5 max-w-lg text-sm leading-6 text-muted-foreground sm:text-[15px]">Turn environments, characters and stories into a consistent visual system for every shot.</p><div className="mt-7 flex flex-wrap gap-2"><Button onClick={onCreate} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-4 w-4" />Create project</Button><Button variant="outline" onClick={onAI}><Sparkles className="h-4 w-4 text-cyan-strong" />Open Production AI</Button></div></div><div className="relative hidden h-full min-h-[286px] overflow-hidden md:block"><img src={apartmentImage} alt="Blue-hour apartment production world" className="h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-r from-card via-card/20 to-transparent" /><div className="absolute bottom-5 right-6 rounded-lg border border-primary-foreground/20 bg-foreground/80 px-3 py-2 text-[10px] text-primary-foreground backdrop-blur"><span className="text-primary-foreground/60">Current context</span><br /><strong>Home Film POC / Apartment</strong></div></div></div></section><div className="mb-12"><SectionHeading title="Recent projects" action={<Button variant="ghost" size="sm" onClick={() => go("projects")} className="text-muted-foreground">View all <ArrowRight className="h-3.5 w-3.5" /></Button>} /><div className="grid gap-4 md:grid-cols-3">{projects.map((project, index) => <ProjectCard key={project.name} project={project} featured={index === 0} onClick={() => go(index === 0 ? "project" : "projects")} />)}</div></div><div className="mb-12"><SectionHeading title="Your production world" action={<Button variant="ghost" size="sm" onClick={() => go("assets")} className="text-muted-foreground">Open library <ArrowRight className="h-3.5 w-3.5" /></Button>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><WorldCard title="Characters" count="08" meta="identities" image={mayaImage} onClick={() => go("characters")} /><WorldCard title="Locations" count="06" meta="production-ready" image={apartmentImage} onClick={() => go("locations")} /><WorldCard title="Props" count="42" meta="states tracked" image={studioImage} onClick={() => go("props")} /><WorldCard title="Wardrobe" count="14" meta="looks confirmed" image={rooftopImage} onClick={() => go("assets")} /></div></div><div className="mb-12"><SectionHeading title="Production pipeline" action={<span className="text-xs text-muted-foreground">Everything stays in context</span>} /><Pipeline go={go} /></div><div><SectionHeading title="Recent activity" action={<Button variant="ghost" size="sm" onClick={() => go("history")} className="text-muted-foreground">Open history <ArrowRight className="h-3.5 w-3.5" /></Button>} /><ActivityList /></div></div>;
}

function SectionHeading({ title, action }: { title: string; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold tracking-[-0.025em]">{title}</h2>{action}</div>; }

function ProjectCard({ project, featured, onClick }: { project: typeof projects[number]; featured?: boolean; onClick: () => void }) { return <button onClick={onClick} className={`group relative overflow-hidden rounded-xl border border-border bg-card text-left shadow-sm transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md ${featured ? "md:col-span-1" : ""}`}><div className="relative aspect-[16/10] overflow-hidden"><img src={project.image} alt={`${project.name} cover`} loading="lazy" width={1280} height={800} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/80 via-transparent to-transparent" /><div className="absolute left-4 top-4"><Badge className="border-0 bg-primary-foreground/90 text-foreground">{project.status}</Badge></div><div className="absolute bottom-4 left-4 right-4 flex items-end justify-between text-primary-foreground"><span className="text-base font-semibold">{project.name}</span><ArrowUpRight className="h-4 w-4 opacity-0 transition-opacity group-hover:opacity-100" /></div></div><div className="grid grid-cols-2 gap-y-2 px-4 py-3 text-[11px] text-muted-foreground">{project.stats.map((stat) => <span key={stat}>{stat}</span>)}<span className="col-span-2 pt-1 text-[10px] text-muted-foreground/70">{project.updated}</span></div></button>; }

function WorldCard({ title, count, meta, image, onClick }: { title: string; count: string; meta: string; image: ImageSrc; onClick: () => void }) { return <button onClick={onClick} className="group overflow-hidden rounded-xl border border-border bg-card text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md"><div className="relative aspect-[4/3] overflow-hidden"><img src={image} alt={title} loading="lazy" width={1280} height={800} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/80 to-transparent" /><div className="absolute bottom-3 left-4 text-primary-foreground"><div className="text-sm font-semibold">{title}</div><div className="mt-0.5 text-[11px] text-primary-foreground/70">{count} {meta}</div></div></div></button>; }

function Pipeline({ go }: { go: (view: View) => void }) { const steps: [string, string, View][] = [["Assets", "42", "assets"], ["World", "08", "locations"], ["Story", "03", "stories"], ["Scenes", "24", "scenes"], ["Shots", "84", "shots"], ["Storyboard", "32", "storyboard"], ["Continuity", "92%", "continuity"]]; return <div className="flex flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-4 sm:p-5">{steps.map(([label, count, view], index) => <div key={label} className="flex items-center gap-2"><button onClick={() => go(view)} className="group flex min-w-[104px] items-center gap-2 rounded-lg p-2 text-left transition-colors hover:bg-cyan-soft"><span className={`grid h-8 w-8 place-items-center rounded-lg ${index === 6 ? "bg-cyan text-primary-foreground" : "bg-muted text-cyan-strong"}`}>{index === 6 ? <CircleDot className="h-4 w-4" /> : <span className="text-xs font-bold">{count}</span>}</span><span><span className="block text-xs font-semibold">{label}</span><span className="block text-[10px] text-muted-foreground">{index === 6 ? "Needs review" : index === 5 ? "Ready" : "In context"}</span></span></button>{index < steps.length - 1 && <ArrowRight className="hidden h-4 w-4 text-border sm:block" />}</div>)}</div>; }

function ActivityList() { const activities = [["Character identity updated", "Maya · Human confirmed", "4 min ago", Users], ["Bedroom reference analyzed", "Apartment · 18 references", "18 min ago", ImageIcon], ["Scene breakdown completed", "The Last Frame · 12 scenes", "42 min ago", Clapperboard], ["Continuity issue detected", "Shot 14 · Coffee cup", "1 hr ago", CircleDot], ["Shot generated", "Scene 04 · Shot 04", "2 hrs ago", WandSparkles]] as const; return <div className="divide-y divide-border rounded-xl border border-border bg-card">{activities.map(([title, meta, time, Icon]) => <div key={title} className="flex items-center gap-3 px-4 py-3.5 sm:px-5"><span className="grid h-8 w-8 place-items-center rounded-lg bg-muted text-cyan-strong"><Icon className="h-4 w-4" /></span><div className="min-w-0 flex-1"><div className="text-sm font-medium">{title}</div><div className="truncate text-xs text-muted-foreground">{meta}</div></div><span className="text-[11px] text-muted-foreground">{time}</span></div>)}</div>; }

function Projects({ go, onCreate }: { go: (view: View) => void; onCreate: () => void }) { return <div><PageHeader eyebrow="Workspace" title="Projects" description="Your productions, worlds and visual stories." action={<Button onClick={onCreate} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-4 w-4" />New project</Button>} /><div className="mb-4 flex items-center justify-between"><span className="text-xs text-muted-foreground">3 productions</span><Button variant="outline" size="sm"><LayoutGrid className="h-3.5 w-3.5" />Grid <ChevronDown className="h-3.5 w-3.5" /></Button></div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{projects.map((project, index) => <ProjectCard key={project.name} project={project} onClick={() => go(index === 0 ? "project" : "projects")} />)}<button onClick={onCreate} className="group flex min-h-[330px] flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card/40 text-muted-foreground transition-colors hover:border-cyan hover:bg-cyan-soft"><span className="mb-3 grid h-12 w-12 place-items-center rounded-xl border border-border bg-card text-cyan"><Plus className="h-5 w-5" /></span><span className="text-sm font-semibold text-foreground">Create a new production</span><span className="mt-1 text-xs">Start with a story or a world</span></button></div></div>; }

function ProjectOverview({ go, onAI }: { go: (view: View) => void; onAI: () => void }) { const journey: [string, string, string, View, string][] = [["Assets", "42 assets", "Ready", "assets", "bg-success"], ["World", "3 locations", "Ready", "locations", "bg-success"], ["Stories", "2 stories", "In progress", "stories", "bg-warning"], ["Scenes", "24 scenes", "Ready", "scenes", "bg-success"], ["Shots", "84 shots", "Draft", "shots", "bg-cyan"], ["Storyboard", "32 frames", "Ready", "storyboard", "bg-success"], ["Continuity", "3 issues", "Needs review", "continuity", "bg-warning"]]; return <div><div className="mb-8 overflow-hidden rounded-2xl border border-border bg-card"><div className="relative h-44"><img src={apartmentImage} alt="Home Film POC apartment" className="h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-r from-foreground/85 via-foreground/40 to-transparent" /><div className="absolute bottom-6 left-7 text-primary-foreground sm:left-9"><div className="mb-2 flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-primary-foreground/70"><Film className="h-3 w-3" />Production workspace</div><h1 className="text-3xl font-bold tracking-[-0.05em]">Home Film POC</h1><p className="mt-1 text-sm text-primary-foreground/70">A quiet apartment. A missing hour. Three people who remember it differently.</p></div><div className="absolute bottom-6 right-7 hidden gap-2 sm:flex"><Button onClick={onAI} variant="outline" className="border-primary-foreground/30 bg-foreground/20 text-primary-foreground hover:bg-foreground/40"><Sparkles className="h-4 w-4" />Production AI</Button><Button onClick={() => go("assets")} className="bg-primary-foreground text-foreground hover:bg-primary-foreground/90"><Plus className="h-4 w-4" />Add asset</Button></div></div><div className="grid grid-cols-3 divide-x divide-border sm:grid-cols-7">{[["Characters", "2", "characters"], ["Locations", "3", "locations"], ["Rooms", "5", "rooms"], ["Props", "18", "props"], ["Stories", "2", "stories"], ["Scenes", "24", "scenes"], ["Shots", "84", "shots"]].map(([label, count, target]) => <button key={label} onClick={() => go(target as View)} className="px-3 py-3 text-left transition-colors hover:bg-accent"><div className="text-lg font-semibold tracking-tight">{count}</div><div className="text-[10px] text-muted-foreground">{label}</div></button>)}</div></div><div className="mb-10"><SectionHeading title="Production journey" action={<span className="text-xs text-muted-foreground">Last synced 4 min ago</span>} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{journey.map(([label, count, status, target, color]) => <button key={label} onClick={() => go(target)} className="group flex items-start gap-3 rounded-xl border border-border bg-card p-4 text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-sm"><span className={`mt-1 h-2 w-2 rounded-full ${color}`} /><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{label}</span><span className="mt-1 block text-xs text-muted-foreground">{count}</span></span><span className={`text-[10px] font-medium ${status === "Needs review" ? "text-warning" : status === "Draft" ? "text-cyan-strong" : "text-success"}`}>{status}</span><ArrowUpRight className="h-3.5 w-3.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" /></button>)}</div></div><div><SectionHeading title="Project activity" /><div className="grid gap-4 lg:grid-cols-[1.15fr_0.85fr]"><div className="rounded-xl border border-border bg-card p-5"><div className="mb-6 flex items-center justify-between"><span className="text-sm font-semibold">Production signal</span><Badge variant="secondary" className="bg-cyan-soft text-cyan-strong">Live context</Badge></div><div className="flex items-end gap-2 border-b border-border pb-5"><div className="text-4xl font-bold tracking-[-0.06em]">92%</div><span className="mb-1 text-xs text-success">+6% this week</span></div><div className="mt-5 flex h-24 items-end gap-1.5">{[35, 45, 41, 58, 55, 67, 62, 76, 72, 86, 83, 92].map((height, index) => <div key={index} className={`flex-1 rounded-t-sm ${index === 11 ? "bg-cyan" : "bg-cyan-soft"}`} style={{ height: `${height}%` }} />)}</div><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Aug 28</span><span>Today</span></div></div><div className="rounded-xl border border-border bg-card p-5"><div className="mb-5 flex items-center justify-between"><span className="text-sm font-semibold">Next best actions</span><Sparkles className="h-4 w-4 text-cyan" /></div>{[["Review 3 continuity issues", "Continuity", "continuity"], ["Complete Shot 04", "Shot planning", "shot"], ["Add wardrobe references", "Maya", "character"]].map(([title, meta, target]) => <button key={title} onClick={() => go(target as View)} className="mb-2 flex w-full items-center gap-3 rounded-lg p-2.5 text-left transition-colors hover:bg-accent"><span className="grid h-7 w-7 place-items-center rounded-md bg-muted text-cyan-strong"><ArrowRight className="h-3.5 w-3.5" /></span><span className="flex-1"><span className="block text-xs font-semibold">{title}</span><span className="block text-[11px] text-muted-foreground">{meta}</span></span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground" /></button>)}</div></div></div></div>; }

function AssetLibrary({ go, onCreate }: { go: (view: View) => void; onCreate: () => void }) { const [tab, setTab] = useState("All"); const filtered = tab === "All" ? assets : assets.filter((item) => item.type === tab.slice(0, -1) || item.type === tab); return <div><PageHeader eyebrow="Production world" title="Assets" description="Everything your production knows about." action={<Button onClick={onCreate} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-4 w-4" />Add asset</Button>} /><div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-1 rounded-lg border border-border bg-card p-1">{["All", "Characters", "Locations", "Props", "Wardrobe"].map((item) => <button key={item} onClick={() => setTab(item)} className={`rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${tab === item ? "bg-foreground text-background" : "text-muted-foreground hover:text-foreground"}`}>{item}</button>)}</div><div className="flex items-center gap-2"><Button variant="outline" size="sm"><span className="h-1.5 w-1.5 rounded-full bg-cyan" />Recently updated <ChevronDown className="h-3.5 w-3.5" /></Button><Button variant="outline" size="sm"><Grid2X2 className="h-3.5 w-3.5" />Grid <ChevronDown className="h-3.5 w-3.5" /></Button></div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{filtered.map((asset) => <AssetCard key={asset.name} asset={asset} onClick={() => go(asset.view)} />)}</div></div>; }

function AssetCard({ asset, onClick }: { asset: typeof assets[number]; onClick: () => void }) { return <button onClick={onClick} className="group overflow-hidden rounded-xl border border-border bg-card text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md"><div className="relative aspect-[4/3] overflow-hidden"><img src={asset.image} alt={asset.name} loading="lazy" width={1280} height={800} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute left-3 top-3"><Badge className="border-0 bg-card/85 text-[10px] uppercase tracking-wide text-foreground backdrop-blur">{asset.type}</Badge></div><div className="absolute bottom-3 right-3 rounded-md bg-foreground/70 px-2 py-1 text-[10px] text-primary-foreground opacity-0 transition-opacity group-hover:opacity-100">Open asset <ArrowUpRight className="ml-1 inline h-3 w-3" /></div></div><div className="p-4"><div className="flex items-start justify-between gap-2"><div><div className="text-sm font-semibold">{asset.name}</div><div className="mt-1 text-xs text-muted-foreground">{asset.refs}</div></div><span className="mt-1 h-2 w-2 rounded-full bg-success" /></div><div className="mt-4 flex items-center justify-between border-t border-border pt-3 text-[10px] text-muted-foreground"><span>{asset.status}</span><span>Edited today</span></div></div></button>; }

function AssetList({ title, eyebrow, description, items, go }: { title: string; eyebrow: string; description: string; items: typeof assets; go: (view: View) => void }) { return <div><PageHeader eyebrow={eyebrow} title={title} description={description} action={<Button onClick={() => toast.success(`${title.slice(0, -1)} creation started`)} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-4 w-4" />Add {title.slice(0, -1)}</Button>} /><div className="mb-5 flex items-center justify-between"><span className="text-xs text-muted-foreground">{items.length} production assets</span><div className="flex gap-2"><Button variant="outline" size="sm"><List className="h-3.5 w-3.5" />List</Button><Button variant="outline" size="sm"><Grid2X2 className="h-3.5 w-3.5" />Grid</Button></div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{items.map((asset) => <AssetCard key={asset.name} asset={asset} onClick={() => go(asset.view)} />)}</div></div>; }

function DetailHeader({ eyebrow, title, subtitle, image, go, action }: { eyebrow: string; title: string; subtitle: string; image: ImageSrc; go: (view: View) => void; action?: ReactNode }) { return <div className="mb-8 flex flex-col gap-5 border-b border-border pb-7 sm:flex-row sm:items-end sm:justify-between"><div className="flex items-center gap-4"><img src={image} alt="" className="h-20 w-20 rounded-xl object-cover" /><div><div className="mb-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-cyan-strong">{eyebrow}</div><h1 className="text-3xl font-bold tracking-[-0.05em]">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{subtitle}</p></div></div><div className="flex flex-wrap items-center gap-2"><Button variant="outline" size="sm" onClick={() => go("assets")}><ArrowLeft className="h-3.5 w-3.5" />Back to library</Button>{action}</div></div>; }

function StatStrip({ items }: { items: [string, string][] }) { return <div className="grid grid-cols-2 divide-x divide-y divide-border rounded-xl border border-border bg-card sm:grid-cols-4 sm:divide-y-0">{items.map(([label, value]) => <div key={label} className="p-4"><div className="text-xl font-bold tracking-[-0.04em]">{value}</div><div className="mt-1 text-[11px] text-muted-foreground">{label}</div></div>)}</div>; }

function InfoBlock({ title, children, action }: { title: string; children: ReactNode; action?: ReactNode }) { return <section className="rounded-xl border border-border bg-card p-5"><div className="mb-4 flex items-center justify-between"><h3 className="text-xs font-semibold uppercase tracking-[0.13em] text-muted-foreground">{title}</h3>{action}</div>{children}</section>; }

function DetailGrid({ rows }: { rows: [string, string][] }) { return <div className="grid grid-cols-2 gap-x-4 gap-y-4">{rows.map(([label, value]) => <div key={label}><div className="text-[11px] text-muted-foreground">{label}</div><div className="mt-1 text-sm font-medium">{value}</div></div>)}</div>; }

function CharacterDetail({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><DetailHeader eyebrow="Character" title="Maya" subtitle="Identity verified · 12 references" image={mayaImage} go={go} action={<><Button variant="outline" size="sm" onClick={() => toast.success("Reference uploader ready")}><Plus className="h-3.5 w-3.5" />Add reference</Button><Button size="sm" onClick={() => onProcess("Character frame generation")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><WandSparkles className="h-3.5 w-3.5" />Generate</Button></>} /><StatStrip items={[["Identity status", "Verified"], ["References", "12"], ["Scenes", "08"], ["Last updated", "Today"]]} /><div className="mt-5 grid gap-5 lg:grid-cols-[1.05fr_0.95fr]"><div className="space-y-5"><InfoBlock title="Identity"><div className="grid gap-4 sm:grid-cols-[0.8fr_1.2fr]"><img src={mayaImage} alt="Maya identity reference" className="aspect-[4/5] w-full rounded-lg object-cover" /><div className="flex flex-col justify-between"><DetailGrid rows={[["Face", "Oval · defined brow"], ["Hair", "Dark bob · side part"], ["Build", "Lean · 170 cm"], ["Skin tone", "Warm olive"], ["Distinctive features", "Small scar above left brow"]]} /><div className="mt-5 rounded-lg bg-cyan-soft p-3 text-xs leading-5 text-cyan-strong"><Sparkles className="mr-1 inline h-3.5 w-3.5" /><strong>Identity verified.</strong> 12 references agree on primary facial features.</div></div></div></InfoBlock><InfoBlock title="Reference gallery"><div className="grid grid-cols-4 gap-2">{[mayaImage, rooftopImage, apartmentImage, mayaImage].map((image, index) => <button key={index} onClick={() => toast.info(`Reference ${index + 1} selected`)} className="group relative aspect-square overflow-hidden rounded-lg"><img src={image} alt={`Maya reference ${index + 1}`} className="h-full w-full object-cover transition-transform group-hover:scale-105" />{index === 3 && <span className="absolute inset-0 grid place-items-center bg-foreground/60 text-sm font-semibold text-primary-foreground">+8</span>}</button>)}</div></InfoBlock></div><div className="space-y-5"><InfoBlock title="Current state" action={<Badge className="bg-cyan-soft text-cyan-strong">Human confirmed</Badge>}><DetailGrid rows={[["Clothing", "Black silk shirt"], ["Emotion", "Worried · contained"], ["Position", "Standing"], ["Action", "Holding phone"], ["Location", "Apartment · Bedroom"], ["Objects held", "Phone"]]} /></InfoBlock><InfoBlock title="Constraints"><div className="space-y-2.5">{["Maintain facial identity", "Maintain hairstyle and silhouette", "Preserve major physical characteristics"].map((item) => <div key={item} className="flex items-center gap-2 text-sm"><Check className="h-4 w-4 text-success" />{item}</div>)}</div></InfoBlock><InfoBlock title="Relationships"><div className="space-y-2">{[["Appears in", "Scene 01 · Scene 03 · Scene 04", "scenes"], ["Located in", "Apartment", "location"], ["Interacts with", "Phone · Coffee Cup", "prop"]].map(([label, value, target]) => <button key={label} onClick={() => go(target as View)} className="flex w-full items-center justify-between rounded-lg p-2 text-left hover:bg-accent"><span><span className="block text-[11px] text-muted-foreground">{label}</span><span className="block text-sm font-medium">{value}</span></span><ArrowUpRight className="h-3.5 w-3.5 text-cyan" /></button>)}</div></InfoBlock><InfoBlock title="History"><Timeline items={[["Identity verified", "Today · 14:08", "success"], ["Wardrobe updated", "Yesterday · 18:41", "cyan"], ["Reference added", "Aug 29 · 09:12", "muted"]]} /></InfoBlock></div></div></div>; }

function LocationDetail({ go }: { go: (view: View) => void }) { return <div><DetailHeader eyebrow="Location" title="Apartment" subtitle="Production-ready · 18 references" image={apartmentImage} go={go} action={<><Button variant="outline" size="sm"><Plus className="h-3.5 w-3.5" />Add photos</Button><Button size="sm" onClick={() => toast.success("Reference analysis queued")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-3.5 w-3.5" />Analyze</Button></>} /><div className="mb-5 flex gap-1 overflow-x-auto border-b border-border">{["Overview", "Rooms", "Objects", "Views", "Spatial", "References", "Cinematic profile", "History"].map((item, index) => <button key={item} onClick={() => item === "Spatial" || item === "Rooms" ? go("rooms") : undefined} className={`whitespace-nowrap border-b-2 px-3 py-3 text-xs font-medium ${index === 0 ? "border-cyan text-foreground" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{item}</button>)}</div><div className="grid gap-5 lg:grid-cols-[1.15fr_0.85fr]"><div className="space-y-5"><div className="relative overflow-hidden rounded-xl border border-border bg-card"><img src={apartmentImage} alt="Apartment production reference" className="aspect-[16/9] w-full object-cover" /><div className="absolute bottom-4 left-4 rounded-lg bg-foreground/75 px-3 py-2 text-xs text-primary-foreground backdrop-blur"><span className="text-primary-foreground/60">Primary location reference</span><br /><strong>Blue hour · Bedroom view</strong></div></div><InfoBlock title="Camera views"><div className="grid grid-cols-2 gap-3">{[["Entrance view", studioImage], ["Window view", apartmentImage], ["Desk view", mayaImage], ["Bed view", rooftopImage]].map(([name, image]) => <button key={name} onClick={() => toast.info(`${name} selected`)} className="group text-left"><img src={image} alt={name} className="aspect-[4/3] w-full rounded-lg object-cover transition-transform group-hover:scale-[1.02]" /><div className="mt-2 text-xs font-medium">{name}</div><div className="text-[10px] text-muted-foreground">4 visible objects</div></button>)}</div></InfoBlock></div><div className="space-y-5"><InfoBlock title="Visual identity"><DetailGrid rows={[["Walls", "Cool white · matte"], ["Floor", "Dark oak"], ["Ceiling", "Concrete beam"], ["Lighting", "Window blue hour"], ["Materials", "Glass · wool · wood"], ["Color palette", "Cyan · charcoal · warm white"]]} /></InfoBlock><InfoBlock title="Architecture"><div className="space-y-2">{["1 window wall", "2 doors", "Bedroom boundary", "Desk niche"].map((item) => <div key={item} className="flex items-center gap-2 text-sm"><span className="h-1.5 w-1.5 rounded-full bg-cyan" />{item}</div>)}</div></InfoBlock><InfoBlock title="Objects" action={<Button variant="ghost" size="sm" onClick={() => go("rooms")} className="h-7 text-xs">Open spatial view <ArrowRight className="h-3 w-3" /></Button>}><div className="grid grid-cols-2 gap-2">{["Bed", "Desk", "Chair", "Wardrobe", "Lamp", "Window"].map((item) => <div key={item} className="rounded-lg bg-muted px-3 py-2 text-xs font-medium">{item}</div>)}</div></InfoBlock></div></div></div>; }

function RoomView({ go }: { go: (view: View) => void }) { const hotspots: [string, string, string, string][] = [["Window", "left-[37%] top-[24%]", "Location view · 8 scenes", "High"], ["Bed", "right-[27%] top-[63%]", "Prop · 4 scenes", "High"], ["Desk", "left-[18%] bottom-[20%]", "Prop · 6 scenes", "Medium"], ["Chair", "left-[31%] bottom-[14%]", "Prop · 3 scenes", "Medium"], ["Door", "right-[7%] top-[31%]", "Architecture", "High"]]; return <div><PageHeader eyebrow="Rooms / Apartment" title="Bedroom" description="Approximate spatial layout for story and shot context." action={<><Button variant="outline" size="sm" onClick={() => go("location")}><ArrowLeft className="h-3.5 w-3.5" />Apartment</Button><Button onClick={() => toast.success("Room analysis queued")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-4 w-4" />Analyze room</Button></>} /><div className="grid gap-5 lg:grid-cols-[1.25fr_0.75fr]"><div className="relative overflow-hidden rounded-xl border border-border bg-card"><img src={apartmentImage} alt="Bedroom spatial view" className="aspect-[4/3] w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/30 to-transparent" />{hotspots.map(([name, position, meta, confidence]) => <button key={name} onClick={() => go(name === "Window" ? "location" : "prop")} className={`group absolute ${position} flex -translate-x-1/2 -translate-y-1/2 items-center gap-2`}><span className="grid h-6 w-6 place-items-center rounded-full border-2 border-primary-foreground bg-cyan shadow-lg transition-transform group-hover:scale-125"><span className="h-1.5 w-1.5 rounded-full bg-primary-foreground" /></span><span className="hidden rounded-md bg-foreground/80 px-2 py-1 text-left text-[10px] text-primary-foreground backdrop-blur group-hover:block"><strong>{name}</strong><br /><span className="text-primary-foreground/70">{meta}</span><br /><span className="text-cyan">{confidence} confidence</span></span></button>)}<div className="absolute bottom-4 left-4 rounded-lg border border-primary-foreground/20 bg-foreground/70 px-3 py-2 text-[10px] text-primary-foreground backdrop-blur"><MapPin className="mr-1 inline h-3 w-3 text-cyan" />Approximate spatial layout</div></div><div className="space-y-5"><InfoBlock title="Room context"><DetailGrid rows={[["Location", "Apartment"], ["Time", "Evening / blue hour"], ["Lighting", "Window light + desk lamp"], ["Views", "4 camera views"]]} /></InfoBlock><InfoBlock title="Mapped objects"><div className="space-y-2">{hotspots.map(([name, , meta, confidence]) => <button key={name} onClick={() => go(name === "Window" ? "location" : "prop")} className="flex w-full items-center gap-3 rounded-lg p-2 text-left hover:bg-accent"><span className="h-2 w-2 rounded-full bg-cyan" /><span className="flex-1"><span className="block text-sm font-medium">{name}</span><span className="block text-[10px] text-muted-foreground">{meta}</span></span><span className="text-[10px] text-success">{confidence}</span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground" /></button>)}</div></InfoBlock><InfoBlock title="Suggested coverage"><div className="flex flex-wrap gap-2">{["Establishing wide", "Desk insert", "Window silhouette", "Over shoulder"].map((item) => <Badge key={item} variant="secondary" className="bg-cyan-soft text-cyan-strong">{item}</Badge>)}</div></InfoBlock></div></div></div>; }

function PropDetail({ go }: { go: (view: View) => void }) { return <div><DetailHeader eyebrow="Prop" title="Phone" subtitle="State tracked · 6 references" image={apartmentImage} go={go} action={<Button size="sm" onClick={() => toast.success("Prop reference added")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-3.5 w-3.5" />Add reference</Button>} /><div className="grid gap-5 lg:grid-cols-[0.9fr_1.1fr]"><div className="space-y-5"><div className="overflow-hidden rounded-xl border border-border bg-card"><img src={apartmentImage} alt="Phone prop in apartment" className="aspect-[4/3] w-full object-cover" /></div><InfoBlock title="Identity"><DetailGrid rows={[["Type", "Mobile phone"], ["References", "6 images"], ["Color", "Graphite black"], ["Distinctive", "Hairline crack · top right"]]} /></InfoBlock></div><div className="space-y-5"><InfoBlock title="Current state" action={<Badge className="bg-cyan-soft text-cyan-strong">Active</Badge>}><DetailGrid rows={[["Location", "Apartment / Desk"], ["Condition", "Intact · screen lit"], ["Owner", "Maya"], ["Position", "Face up"], ["Last changed", "Scene 04"]]} /></InfoBlock><InfoBlock title="State history"><Timeline items={[["Floor · damaged", "Scene 04 · current", "warning"], ["Desk · idle", "Scene 03 · 16:12", "muted"], ["Character's hand · active", "Scene 02 · 15:58", "cyan"], ["Desk · idle", "Scene 01 · 15:30", "muted"]]} /></InfoBlock><InfoBlock title="Relationships"><div className="grid gap-2 sm:grid-cols-2">{[["Held by", "Maya", "character"], ["Located in", "Apartment", "location"], ["Changes state in", "Scene 04", "scene"], ["Appears in", "6 shots", "shots"]].map(([label, value, target]) => <button key={label} onClick={() => go(target as View)} className="rounded-lg bg-muted p-3 text-left transition-colors hover:bg-cyan-soft"><div className="text-[10px] text-muted-foreground">{label}</div><div className="mt-1 text-sm font-semibold">{value}</div></button>)}</div></InfoBlock></div></div></div>; }

function Timeline({ items }: { items: [string, string, string][] }) { return <div className="space-y-0">{items.map(([title, meta, tone], index) => <div key={title} className="relative flex gap-3 pb-4 last:pb-0"><div className="relative flex w-3 justify-center"><span className={`z-10 mt-1.5 h-2 w-2 rounded-full ${tone === "success" ? "bg-success" : tone === "warning" ? "bg-warning" : tone === "cyan" ? "bg-cyan" : "bg-border"}`} />{index < items.length - 1 && <span className="absolute top-3 h-full w-px bg-border" />}</div><div><div className="text-xs font-medium">{title}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{meta}</div></div></div>)}</div>; }

function Stories({ go, onCreate }: { go: (view: View) => void; onCreate: () => void }) { const storyCards = [{ title: "The Last Frame", status: "Draft", scenes: "12 scenes", shots: "48 shots", image: rooftopImage }, { title: "Before Sunrise", status: "In development", scenes: "08 scenes", shots: "31 shots", image: apartmentImage }, { title: "Silent Signal", status: "Outline", scenes: "05 scenes", shots: "18 shots", image: studioImage }]; return <div><PageHeader eyebrow="Story intelligence" title="Stories" description="Turn ideas into production-ready visual plans." action={<Button onClick={onCreate} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Plus className="h-4 w-4" />New story</Button>} /><div className="mb-9 grid gap-5 lg:grid-cols-[1.2fr_0.8fr]"><div className="relative overflow-hidden rounded-2xl border border-border bg-foreground p-7 text-primary-foreground sm:p-9"><div className="absolute right-0 top-0 h-full w-2/5 opacity-50"><img src={rooftopImage} alt="" className="h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-r from-foreground to-transparent" /></div><div className="relative max-w-lg"><div className="mb-3 flex items-center gap-2 text-xs text-cyan"><Sparkles className="h-4 w-4" />AI creative composer</div><h2 className="text-3xl font-bold tracking-[-0.05em] sm:text-4xl">Start with a feeling.<br />Build the sequence.</h2><p className="mt-4 text-sm leading-6 text-primary-foreground/65">Describe the story in your own words. FRAMEFLOW will connect it to your production world.</p><button onClick={onCreate} className="mt-6 flex w-full items-center justify-between rounded-xl border border-primary-foreground/20 bg-primary-foreground/10 p-4 text-left text-sm text-primary-foreground/70 backdrop-blur transition-colors hover:bg-primary-foreground/15"><span>Describe your story…</span><ArrowRight className="h-4 w-4 text-cyan" /></button><div className="mt-4 flex flex-wrap gap-2">{["Character-driven story", "Single-location scene", "Visual treatment"].map((item) => <button key={item} onClick={onCreate} className="rounded-full border border-primary-foreground/15 px-3 py-1.5 text-[10px] text-primary-foreground/65 hover:border-cyan hover:text-cyan">{item}</button>)}</div></div></div><div className="rounded-2xl border border-border bg-card p-6"><div className="mb-5 flex items-center justify-between"><span className="text-sm font-semibold">Story intelligence</span><BrainCircuit className="h-4 w-4 text-cyan" /></div><div className="space-y-4">{[["World context", "All 42 assets available", "success"], ["State transitions", "3 moments detected", "cyan"], ["Potential concerns", "2 to review", "warning"]].map(([label, value, tone]) => <div key={label} className="flex items-center justify-between"><span className="text-sm text-muted-foreground">{label}</span><span className={`text-xs font-medium ${tone === "success" ? "text-success" : tone === "warning" ? "text-warning" : "text-cyan-strong"}`}>{value}</span></div>)}</div><div className="my-6 border-t border-border" /><div className="text-xs leading-5 text-muted-foreground">The composer keeps character identity, location layout and prop state in view while you write.</div></div></div><SectionHeading title="Your stories" action={<span className="text-xs text-muted-foreground">3 stories</span>} /><div className="grid gap-4 md:grid-cols-3">{storyCards.map((story, index) => <button key={story.title} onClick={() => go(index === 0 ? "story" : "stories")} className="group overflow-hidden rounded-xl border border-border bg-card text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md"><div className="relative aspect-[16/10] overflow-hidden"><img src={story.image} alt={story.title} loading="lazy" className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/80 to-transparent" /><Badge className="absolute left-3 top-3 border-0 bg-card/90 text-foreground">{story.status}</Badge><div className="absolute bottom-3 left-4 text-primary-foreground"><div className="font-semibold">{story.title}</div><div className="mt-1 text-[10px] text-primary-foreground/65">{story.scenes} · {story.shots}</div></div></div><div className="flex items-center justify-between p-4 text-[11px] text-muted-foreground"><span>2 characters · 3 locations</span><span>Edited today</span></div></button>)}</div></div>; }

function StoryDetail({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><PageHeader eyebrow="Story / Draft" title="The Last Frame" description="A character-driven sequence about what remains after the image is gone." action={<><Button variant="outline" size="sm"><Ellipsis className="h-4 w-4" />More</Button><Button onClick={() => onProcess("Scene breakdown", "scenes")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-4 w-4" />Generate scenes</Button></>} /><div className="grid gap-5 lg:grid-cols-[1fr_340px]"><div className="space-y-5"><div className="rounded-xl border border-border bg-card p-6 sm:p-8"><div className="mb-5 flex items-center gap-2 text-xs text-cyan-strong"><Badge className="bg-cyan-soft text-cyan-strong">Draft</Badge><span>Last edited 14 min ago</span></div><p className="max-w-2xl text-lg leading-8 tracking-[-0.02em]">Maya returns to the apartment after a long absence. A phone left on the desk begins to replay a night she thought she had forgotten. As the city changes outside the window, Daniel arrives with the one frame that could explain everything.</p><div className="mt-8 flex flex-wrap gap-2">{["quiet tension", "blue hour", "memory", "single location"].map((tag) => <Badge key={tag} variant="secondary" className="bg-muted text-muted-foreground">{tag}</Badge>)}</div></div><InfoBlock title="Scene structure"><div className="space-y-2">{[["01", "The return", "Apartment · Evening", "5 shots"], ["02", "The signal", "Apartment · Night", "6 shots"], ["03", "The frame", "Rooftop · Dawn", "8 shots"]].map(([number, title, meta, shotsCount]) => <button key={number} onClick={() => go("scene")} className="flex w-full items-center gap-4 rounded-lg p-3 text-left transition-colors hover:bg-accent"><span className="font-mono text-xs text-cyan">{number}</span><span className="flex-1"><span className="block text-sm font-semibold">{title}</span><span className="block text-[11px] text-muted-foreground">{meta}</span></span><span className="text-[11px] text-muted-foreground">{shotsCount}</span><ChevronRight className="h-4 w-4 text-muted-foreground" /></button>)}</div></InfoBlock></div><div className="space-y-5"><InfoBlock title="Production context"><div className="space-y-3">{[["Characters", "Maya · Daniel", "characters"], ["Locations", "Apartment · Rooftop", "locations"], ["Props", "Phone · Coffee cup", "props"]].map(([label, value, target]) => <button key={label} onClick={() => go(target as View)} className="flex w-full items-center justify-between rounded-lg bg-muted p-3 text-left hover:bg-cyan-soft"><span><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">{label}</span><span className="block mt-1 text-sm font-medium">{value}</span></span><ArrowUpRight className="h-3.5 w-3.5 text-cyan" /></button>)}</div></InfoBlock><InfoBlock title="AI suggestions"><div className="space-y-3">{["Add a reaction beat before Scene 02", "Phone state changes across 3 scenes", "Rooftop needs one more reference"].map((item) => <div key={item} className="flex gap-2 text-xs leading-5"><Sparkles className="mt-0.5 h-3.5 w-3.5 shrink-0 text-cyan" />{item}</div>)}</div></InfoBlock></div></div></div>; }

function Scenes({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { const sceneData = [["01", "The return", "Apartment", "Evening", "Maya", apartmentImage, "5 shots"], ["02", "The signal", "Apartment", "Night", "Maya · Daniel", studioImage, "6 shots"], ["03", "The frame", "Rooftop", "Dawn", "Daniel", rooftopImage, "8 shots"], ["04", "What remains", "Apartment", "Blue hour", "Maya", mayaImage, "5 shots"]]; return <div><PageHeader eyebrow="Story / The Last Frame" title="Scenes" description="A visual breakdown of the story into production-ready moments." action={<Button onClick={() => onProcess("Scene structure", "scenes")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-4 w-4" />Generate scenes</Button>} /><div className="mb-6 flex items-center justify-between"><div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 rounded-full bg-success" />12 scenes ready</div><Button variant="outline" size="sm"><List className="h-3.5 w-3.5" />List view</Button></div><div className="grid gap-4 md:grid-cols-2">{sceneData.map(([number, title, location, time, characters, image, shotsCount]) => <button key={number} onClick={() => go("scene")} className="group overflow-hidden rounded-xl border border-border bg-card text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md"><div className="relative aspect-[16/9] overflow-hidden"><img src={image} alt={`${title} scene`} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/85 via-transparent to-transparent" /><div className="absolute left-4 top-4 rounded-md bg-foreground/70 px-2 py-1 font-mono text-xs text-primary-foreground">SCENE {number}</div><div className="absolute bottom-4 left-4 right-4 text-primary-foreground"><div className="flex items-center justify-between"><div><div className="text-base font-semibold">{title}</div><div className="mt-1 text-xs text-primary-foreground/70">{location} · {time}</div></div><ArrowUpRight className="h-4 w-4 opacity-0 transition-opacity group-hover:opacity-100" /></div></div></div><div className="flex items-center justify-between p-4 text-[11px] text-muted-foreground"><span>{characters} · 3 props</span><span className="text-success">{shotsCount} · Ready</span></div></button>)}</div></div>; }

function SceneDetail({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><PageHeader eyebrow="Scene 04 / Apartment" title="What remains" description="Apartment · Blue hour · 2 characters · 5 shots" action={<><Button variant="outline" size="sm"><Ellipsis className="h-4 w-4" />Edit</Button><Button onClick={() => onProcess("Shot plan", "shots")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Aperture className="h-4 w-4" />Generate shots</Button></>} /><div className="grid gap-5 lg:grid-cols-[1fr_350px]"><div className="space-y-5"><div className="overflow-hidden rounded-xl border border-border bg-card"><div className="relative"><img src={apartmentImage} alt="Scene 04 apartment context" className="aspect-[16/7] w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/70 to-transparent" /><div className="absolute bottom-5 left-5 text-primary-foreground"><div className="text-xs text-primary-foreground/65">Scene context</div><div className="mt-1 text-xl font-semibold">The phone is still warm.</div></div></div><div className="p-5"><div className="mb-4 text-xs font-semibold uppercase tracking-[0.13em] text-muted-foreground">Action timeline</div><div className="space-y-4">{[["01", "Maya enters", "She pauses at the threshold, listening."], ["02", "The phone lights", "A message arrives from an unknown number."], ["03", "Daniel appears", "He knows what she is about to see."]].map(([number, title, copy]) => <div key={number} className="flex gap-4"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-cyan-soft font-mono text-[10px] font-bold text-cyan-strong">{number}</span><div><div className="text-sm font-semibold">{title}</div><div className="mt-1 text-xs leading-5 text-muted-foreground">{copy}</div></div></div>)}</div></div></div><InfoBlock title="Shot plan"><div className="flex gap-2 overflow-x-auto pb-1">{shots.slice(0, 5).map((shot) => <button key={shot.number} onClick={() => go("shot")} className="min-w-32 rounded-lg border border-border p-2 text-left hover:border-cyan/40"><img src={shot.image} alt={shot.type} className="aspect-[4/3] w-full rounded-md object-cover" /><div className="mt-2 font-mono text-[10px] text-cyan">{shot.number}</div><div className="text-xs font-medium">{shot.type}</div></button>)}</div></InfoBlock></div><div className="space-y-5"><InfoBlock title="Character state"><StateRows rows={[["Maya", "Black silk shirt · worried · standing"], ["Daniel", "Dark jacket · guarded · doorway"]]} /></InfoBlock><InfoBlock title="Prop state"><StateRows rows={[["Phone", "Desk → Maya's hand · active"], ["Coffee cup", "Desk · intact · idle"], ["Backpack", "Floor · closed"]]} /></InfoBlock><InfoBlock title="Location state"><StateRows rows={[["Lighting", "Blue hour · desk lamp on"], ["Windows", "Open · city visible"], ["Environment", "Rain starting"]]} /></InfoBlock></div></div></div>; }

function StateRows({ rows }: { rows: [string, string][] }) { return <div className="space-y-2">{rows.map(([label, value]) => <div key={label} className="rounded-lg bg-muted p-3"><div className="text-xs font-semibold">{label}</div><div className="mt-1 text-[11px] leading-5 text-muted-foreground">{value}</div></div>)}</div>; }

function Shots({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><PageHeader eyebrow="Scene 04 / Shot planning" title="Shot plan" description="AI-proposed coverage grounded in the apartment, characters and prop states." action={<Button onClick={() => onProcess("Shot planning", "shots")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><RefreshCcw className="h-4 w-4" />Regenerate plan</Button>} /><div className="mb-7 flex items-center gap-3 rounded-xl border border-cyan/30 bg-cyan-soft p-4 text-sm"><span className="grid h-8 w-8 place-items-center rounded-lg bg-card text-cyan"><Sparkles className="h-4 w-4" /></span><span className="flex-1"><strong>Production-aware plan ready.</strong><span className="ml-1 text-muted-foreground">6 shots cover the emotional beat while preserving continuity.</span></span><Badge className="hidden bg-card text-cyan-strong sm:flex">AI Recommended</Badge></div><div className="flex gap-4 overflow-x-auto pb-4">{shots.map((shot) => <ShotCard key={shot.number} shot={shot} onClick={() => go("shot")} />)}</div><div className="mt-4 grid gap-5 lg:grid-cols-[1fr_340px]"><InfoBlock title="Coverage notes"><div className="space-y-3 text-sm leading-6 text-muted-foreground"><p>The plan moves from environment to identity to the object that carries the scene's state transition.</p><p>Shot 04 is flagged for review because the phone state changes between Scene 03 and Scene 04.</p></div></InfoBlock><InfoBlock title="Plan context"><DetailGrid rows={[["Characters", "Maya · Daniel"], ["Location", "Apartment / Bedroom"], ["Props", "Phone · Coffee cup"], ["Continuity", "1 issue to review"]]} /></InfoBlock></div></div>; }

function ShotCard({ shot, onClick }: { shot: typeof shots[number]; onClick: () => void }) { return <button onClick={onClick} className="group w-[255px] shrink-0 overflow-hidden rounded-xl border border-border bg-card text-left transition-all hover:-translate-y-0.5 hover:border-cyan/40 hover:shadow-md"><div className="relative aspect-[4/3] overflow-hidden"><img src={shot.image} alt={`Shot ${shot.number} ${shot.type}`} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute left-3 top-3 rounded-md bg-foreground/75 px-2 py-1 font-mono text-[10px] text-primary-foreground">SHOT {shot.number}</div><Badge className={`absolute right-3 top-3 border-0 ${shot.status === "Approved" ? "bg-success text-primary-foreground" : shot.status === "Review" ? "bg-warning text-foreground" : "bg-card/90 text-foreground"}`}>{shot.status}</Badge><div className="absolute bottom-3 left-3 text-primary-foreground"><div className="text-sm font-semibold">{shot.type}</div></div></div><div className="p-4"><div className="text-sm font-medium">{shot.copy}</div><div className="mt-3 flex items-center justify-between text-[10px] text-muted-foreground"><span>Camera · 50mm</span><span>3 refs</span></div><div className="mt-3 flex gap-1.5"><Button variant="outline" size="sm" className="h-7 flex-1 text-[10px]" onClick={(event) => { event.stopPropagation(); toast.success(`Shot ${shot.number} approved`); }}><Check className="h-3 w-3" />Approve</Button><Button variant="ghost" size="sm" className="h-7 px-2" onClick={(event) => { event.stopPropagation(); toast.info("Shot editor opened"); }} aria-label={`Edit shot ${shot.number}`}><Ellipsis className="h-3.5 w-3.5" /></Button></div></div></button>; }

function ShotDetail({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><PageHeader eyebrow="Shot 04 / Scene 04" title="Medium close-up" description="Maya reads the message. The room holds its breath." action={<><Button variant="outline" size="sm"><Ellipsis className="h-4 w-4" />Edit</Button><Button onClick={() => onProcess("Reference compilation", "shot")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><WandSparkles className="h-4 w-4" />Generate frame</Button></>} /><div className="grid gap-5 xl:grid-cols-[220px_1fr_290px]"><div className="order-2 space-y-5 xl:order-1"><InfoBlock title="References"><ReferenceThumb label="Character" image={mayaImage} onClick={() => go("character")} /><ReferenceThumb label="Location" image={apartmentImage} onClick={() => go("location")} /><div className="mt-3 grid grid-cols-3 gap-2">{[studioImage, rooftopImage, apartmentImage].map((image, index) => <img key={index} src={image} alt={`Prop reference ${index + 1}`} className="aspect-square rounded-md object-cover" />)}</div></InfoBlock><InfoBlock title="Production state"><DetailGrid rows={[["Clothing", "Black silk shirt"], ["Emotion", "Worried"], ["Position", "Standing"], ["Action", "Holding phone"]]} /></InfoBlock></div><ReferenceCompiler onGenerate={() => onProcess("Reference compilation", "shot")} /><div className="order-3 space-y-5"><InfoBlock title="Shot intelligence"><DetailGrid rows={[["Shot type", "Medium close-up"], ["Camera", "50mm · eye level"], ["Character", "Maya"], ["Location", "Apartment"], ["Action", "Reads message"], ["State", "Phone active"]]} /></InfoBlock><InfoBlock title="Constraints"><div className="space-y-2 text-xs">{["Facial identity", "Window layout", "Phone state", "Black silk shirt"].map((item) => <div key={item} className="flex items-center gap-2"><Check className="h-3.5 w-3.5 text-success" />{item}</div>)}</div></InfoBlock><InfoBlock title="Continuity"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full border-4 border-cyan-soft text-xs font-bold text-cyan-strong">92%</span><div><div className="text-sm font-semibold">Needs review</div><div className="mt-1 text-[11px] text-muted-foreground">Phone state differs from Shot 03.</div></div></div><Button variant="outline" size="sm" className="mt-4 w-full" onClick={() => go("continuity")}>Review continuity</Button></InfoBlock></div></div></div>; }

function ReferenceThumb({ label, image, onClick }: { label: string; image: ImageSrc; onClick: () => void }) { return <button onClick={onClick} className="mb-3 flex w-full items-center gap-2 text-left"><img src={image} alt={label} className="h-12 w-16 rounded-md object-cover" /><span><span className="block text-xs font-medium">{label}</span><span className="block text-[10px] text-muted-foreground">4 selected</span></span><ArrowUpRight className="ml-auto h-3.5 w-3.5 text-cyan" /></button>; }

function ReferenceCompiler({ onGenerate }: { onGenerate: () => void }) { const items = [["Character references", mayaImage], ["Location references", apartmentImage], ["Prop references", studioImage]] as const; return <div className="order-1 overflow-hidden rounded-xl border border-border bg-card xl:order-2"><div className="border-b border-border bg-foreground px-6 py-5 text-primary-foreground"><div className="flex items-center gap-2 text-xs text-cyan"><Sparkles className="h-4 w-4" />Reference compiler</div><h2 className="mt-2 text-xl font-semibold tracking-[-0.035em]">Prepare shot context</h2><p className="mt-1 text-xs leading-5 text-primary-foreground/60">FRAMEFLOW compiles the right production context before calling a rendering model.</p></div><div className="p-6"><div className="space-y-4">{items.map(([label, image], index) => <div key={label} className="flex items-center gap-3"><div className="relative"><img src={image} alt={label} className="h-14 w-20 rounded-lg object-cover" /><span className="absolute -right-1 -top-1 grid h-4 w-4 place-items-center rounded-full bg-success text-[9px] text-primary-foreground"><Check className="h-2.5 w-2.5" /></span></div><div className="flex-1"><div className="text-sm font-medium">{label}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{index === 0 ? "Maya · 4 selected" : index === 1 ? "Apartment · 6 selected" : "Phone · 3 selected"}</div></div></div>)}</div><div className="my-6 border-t border-border" /><div className="mb-3 text-xs font-semibold uppercase tracking-[0.13em] text-muted-foreground">Production state</div><div className="grid grid-cols-2 gap-2">{[["Clothing", "Black silk shirt"], ["Emotion", "Worried"], ["Position", "Standing"], ["Action", "Holding phone"]].map(([label, value]) => <div key={label} className="rounded-lg bg-muted p-2.5"><div className="text-[10px] text-muted-foreground">{label}</div><div className="mt-1 text-xs font-medium">{value}</div></div>)}</div><div className="my-6 border-t border-border" /><div className="mb-3 text-xs font-semibold uppercase tracking-[0.13em] text-muted-foreground">Context ready</div><div className="space-y-2">{["Character identity", "Location layout", "Prop state", "Continuity constraints"].map((item) => <div key={item} className="flex items-center gap-2 text-xs"><Check className="h-3.5 w-3.5 text-success" />{item}</div>)}</div><Button onClick={onGenerate} className="mt-6 w-full bg-cyan text-primary-foreground hover:bg-cyan-strong"><WandSparkles className="h-4 w-4" />Generate frame <ArrowRight className="ml-auto h-4 w-4" /></Button></div></div>; }

function Storyboard({ go }: { go: (view: View) => void }) { const [selected, setSelected] = useState(3); return <div><PageHeader eyebrow="Visual production sequence" title="Storyboard" description="See the production as a sequence, not a list." action={<div className="flex gap-1 rounded-lg border border-border bg-card p-1"><Button variant="secondary" size="sm"><Grid2X2 className="h-3.5 w-3.5" />Grid</Button><Button variant="ghost" size="sm"><List className="h-3.5 w-3.5" />Timeline</Button><Button variant="ghost" size="icon" className="h-8 w-8" aria-label="Fullscreen"><Maximize2 className="h-3.5 w-3.5" /></Button></div>} /><div className="mb-6 flex items-center justify-between"><div className="flex items-center gap-2"><Button variant="outline" size="sm">Scene 04 · What remains <ChevronDown className="h-3.5 w-3.5" /></Button><Badge className="bg-success/15 text-success">32 frames ready</Badge></div><span className="text-xs text-muted-foreground">Drag to reorder</span></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{shots.map((shot, index) => <button key={shot.number} onClick={() => setSelected(index)} className={`group overflow-hidden rounded-xl border bg-card text-left transition-all ${selected === index ? "border-cyan ring-2 ring-cyan/20" : "border-border hover:border-cyan/40"}`}><div className="relative aspect-[16/10] overflow-hidden"><img src={shot.image} alt={`Storyboard frame ${shot.number}`} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-foreground/70 via-transparent to-transparent" /><div className="absolute left-3 top-3 rounded bg-foreground/75 px-2 py-1 font-mono text-[10px] text-primary-foreground">{shot.number}</div><div className="absolute bottom-3 left-3 text-primary-foreground"><div className="text-sm font-semibold">{shot.type}</div><div className="text-[10px] text-primary-foreground/70">Continuity {index === 3 ? "92%" : "98%"}</div></div><span className="absolute right-3 top-3 h-2 w-2 rounded-full bg-success" /></div><div className="flex items-center justify-between p-3"><span className="text-xs font-medium">{shot.copy}</span><ArrowUpRight className="h-3.5 w-3.5 text-cyan opacity-0 transition-opacity group-hover:opacity-100" /></div></button>)}</div><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_320px]"><InfoBlock title="Sequence note"><div className="flex gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-cyan-soft text-cyan"><Film className="h-4 w-4" /></span><p className="text-sm leading-6 text-muted-foreground">The visual rhythm narrows as Maya reaches the phone, then opens again when Daniel enters the frame.</p></div></InfoBlock><InfoBlock title={`Shot ${shots[selected]?.number ?? "04"} inspector`}><DetailGrid rows={[["Character", "Maya"], ["Location", "Apartment"], ["Props", "Phone"], ["State", "Worried · standing"], ["References", "4 selected"]]} /><div className="mt-4 flex gap-2"><Button size="sm" onClick={() => go("shot")} className="flex-1 bg-cyan text-primary-foreground hover:bg-cyan-strong">Open shot</Button><Button variant="outline" size="sm" onClick={() => toast.success("Frame queued for regeneration")}><RefreshCcw className="h-3.5 w-3.5" /></Button></div></InfoBlock></div></div>; }

function Continuity({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { const categories = [["Character", "96%", "Consistent", "success"], ["Location", "94%", "Consistent", "success"], ["Props", "88%", "3 issues", "warning"], ["State", "91%", "1 issue", "warning"]]; return <div><PageHeader eyebrow="Production intelligence" title="Continuity" description="Protect production consistency across every scene." action={<Button onClick={() => onProcess("Continuity review")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-4 w-4" />Check continuity</Button>} /><div className="mb-7 grid gap-5 lg:grid-cols-[0.8fr_1.2fr]"><div className="rounded-2xl border border-border bg-foreground p-7 text-primary-foreground"><div className="flex items-start justify-between"><div><div className="text-xs text-primary-foreground/60">Project consistency signal</div><div className="mt-3 text-6xl font-bold tracking-[-0.07em]">92<span className="text-3xl text-cyan">%</span></div><div className="mt-2 flex items-center gap-2 text-xs text-success"><ArrowUpRight className="h-3.5 w-3.5" />+4% since last review</div></div><CircleDot className="h-6 w-6 text-cyan" /></div><div className="mt-8 h-2 rounded-full bg-primary-foreground/15"><div className="h-full w-[92%] rounded-full bg-cyan" /></div><div className="mt-2 flex justify-between text-[10px] text-primary-foreground/50"><span>Observed across 84 shots</span><span>Model-assisted signal</span></div></div><div className="grid grid-cols-2 gap-3">{categories.map(([label, score, status, tone]) => <button key={label} onClick={() => tone === "warning" ? go("issue") : undefined} className="rounded-xl border border-border bg-card p-5 text-left transition-colors hover:border-cyan/40"><div className="flex items-start justify-between"><span className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">{label}</span><span className={`h-2 w-2 rounded-full ${tone === "warning" ? "bg-warning" : "bg-success"}`} /></div><div className="mt-4 text-3xl font-bold tracking-[-0.05em]">{score}</div><div className={`mt-1 text-xs ${tone === "warning" ? "text-warning" : "text-success"}`}>{status}</div></button>)}</div></div><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold tracking-[-0.025em]">Continuity review</h2><Button variant="outline" size="sm"><ChevronDown className="h-3.5 w-3.5" />All issues</Button></div><div className="space-y-3">{[["Prop state mismatch", "Shot 14", "Expected coffee cup on desk · observed missing", "warning"], ["Character wardrobe mismatch", "Shot 22", "Expected dark jacket · observed different wardrobe", "warning"], ["Location consistency", "Shot 31", "Window light matches reference context", "success"]].map(([title, shot, copy, tone]) => <button key={title} onClick={() => tone === "warning" ? go("issue") : toast.success("No issue found")} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-cyan/40 hover:shadow-sm"><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-lg ${tone === "warning" ? "bg-warning/15 text-warning" : "bg-success/15 text-success"}`}>{tone === "warning" ? <CircleDot className="h-5 w-5" /> : <Check className="h-5 w-5" />}</span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{title}</span><span className="mt-1 block text-xs text-muted-foreground">{shot} · {copy}</span></span><span className={`hidden text-[10px] font-semibold uppercase tracking-wide sm:block ${tone === "warning" ? "text-warning" : "text-success"}`}>{tone === "warning" ? "Review" : "Consistent"}</span><ChevronRight className="h-4 w-4 text-muted-foreground" /></button>)}</div></div>; }

function ContinuityIssue({ go, onProcess }: { go: (view: View) => void; onProcess: (label: string, next?: View) => void }) { return <div><PageHeader eyebrow="Continuity / Issue review" title="Prop state mismatch" description="Shot 14 · The coffee cup is missing from the desk." action={<><Button variant="outline" size="sm" onClick={() => go("continuity")}><ArrowLeft className="h-3.5 w-3.5" />All issues</Button><Button onClick={() => onProcess("Continuity fix")} className="bg-cyan text-primary-foreground hover:bg-cyan-strong"><Sparkles className="h-4 w-4" />Fix with AI</Button></>} /><div className="mb-6 grid gap-4 lg:grid-cols-2"><div className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border px-5 py-3 text-xs font-semibold uppercase tracking-[0.12em] text-success">Expected</div><div className="relative"><img src={apartmentImage} alt="Expected coffee cup on desk" className="aspect-[16/9] w-full object-cover" /><Badge className="absolute bottom-4 left-4 bg-success text-primary-foreground"><Check className="mr-1 h-3 w-3" />Coffee cup on desk</Badge></div></div><div className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border px-5 py-3 text-xs font-semibold uppercase tracking-[0.12em] text-warning">Observed · Shot 14</div><div className="relative"><img src={mayaImage} alt="Generated shot with missing coffee cup" className="aspect-[16/9] w-full object-cover object-top" /><Badge className="absolute bottom-4 left-4 bg-warning text-foreground"><CircleDot className="mr-1 h-3 w-3" />Prop missing</Badge></div></div></div><div className="grid gap-5 lg:grid-cols-[1fr_330px]"><div className="space-y-5"><InfoBlock title="Issue explanation"><p className="text-sm leading-6 text-muted-foreground">The coffee cup is present in the production state for Scene 04, but it does not appear in the generated frame. This may affect the handoff from Shot 13.</p><div className="mt-4 flex items-center gap-3 rounded-lg bg-warning/10 p-3 text-xs"><span className="h-2 w-2 rounded-full bg-warning" /><span><strong>Confidence: medium.</strong> <span className="text-muted-foreground">Review recommended before accepting.</span></span></div></InfoBlock><InfoBlock title="Suggested resolution"><div className="space-y-3">{["Add coffee cup reference to shot context", "Regenerate with prop state locked", "Check Shot 13 handoff"].map((item, index) => <div key={item} className="flex gap-3"><span className="grid h-6 w-6 place-items-center rounded-full bg-cyan-soft text-[10px] font-semibold text-cyan-strong">{index + 1}</span><span className="text-sm">{item}</span></div>)}</div></InfoBlock></div><div className="space-y-5"><InfoBlock title="Expected state"><DetailGrid rows={[["Prop", "Coffee cup"], ["Location", "Apartment / Desk"], ["Condition", "Intact"], ["Owner", "Maya"]]} /></InfoBlock><InfoBlock title="Review action"><div className="space-y-2"><Button onClick={() => toast.success("Issue accepted", { description: "Continuity state updated." })} className="w-full bg-cyan text-primary-foreground hover:bg-cyan-strong"><Check className="h-4 w-4" />Accept resolution</Button><Button variant="outline" className="w-full" onClick={() => toast.info("State editor opened")}>Edit state</Button><Button variant="ghost" className="w-full" onClick={() => toast.info("Issue ignored for this review")}>Ignore issue</Button></div></InfoBlock></div></div></div>; }

function Relationships({ go }: { go: (view: View) => void }) { const nodes = [{ label: "Apartment", type: "Location", className: "left-[12%] top-[39%]", view: "location" as View }, { label: "Desk", type: "Room object", className: "left-[43%] top-[19%]", view: "rooms" as View }, { label: "Phone", type: "Prop", className: "right-[13%] top-[41%]", view: "prop" as View }, { label: "Maya", type: "Character", className: "left-[43%] bottom-[14%]", view: "character" as View }, { label: "Scene 04", type: "Scene", className: "right-[13%] bottom-[14%]", view: "scene" as View }]; return <div><PageHeader eyebrow="Production world" title="Relationships" description="A clear view of how people, places, props and scenes connect." action={<Button variant="outline" size="sm"><Download className="h-3.5 w-3.5" />Export map</Button>} /><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><div className="relative min-h-[540px] overflow-hidden rounded-xl border border-border bg-card p-5"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: "radial-gradient(var(--border) 1px, transparent 1px)", backgroundSize: "24px 24px" }} /><svg className="absolute inset-0 h-full w-full" aria-hidden="true"><line x1="22%" y1="47%" x2="48%" y2="27%" stroke="var(--cyan)" strokeOpacity=".45" strokeWidth="1.5" /><line x1="52%" y1="29%" x2="81%" y2="47%" stroke="var(--cyan)" strokeOpacity=".45" strokeWidth="1.5" /><line x1="50%" y1="33%" x2="50%" y2="80%" stroke="var(--cyan)" strokeOpacity=".45" strokeWidth="1.5" /><line x1="81%" y1="50%" x2="81%" y2="80%" stroke="var(--cyan)" strokeOpacity=".45" strokeWidth="1.5" /><line x1="54%" y1="82%" x2="78%" y2="82%" stroke="var(--cyan)" strokeOpacity=".45" strokeWidth="1.5" /></svg>{[["contains", "left-[26%] top-[31%]"], ["contains", "left-[65%] top-[31%]"], ["held by", "left-[43%] top-[56%]"], ["changes state in", "right-[22%] top-[65%]"], ["appears in", "left-[65%] bottom-[10%]"]].map(([label, position]) => <span key={label} className={`absolute ${position} rounded-full bg-cyan-soft px-2 py-1 text-[9px] font-medium text-cyan-strong`}>{label}</span>)}{nodes.map((node) => <button key={node.label} onClick={() => go(node.view)} className={`absolute ${node.className} -translate-x-1/2 -translate-y-1/2 rounded-xl border border-border bg-card px-4 py-3 text-left shadow-sm transition-all hover:-translate-y-[calc(50%+2px)] hover:border-cyan hover:shadow-md`}><div className="text-sm font-semibold">{node.label}</div><div className="mt-1 text-[10px] text-muted-foreground">{node.type}</div></button>)}</div><div className="space-y-5"><InfoBlock title="Selected context"><div className="rounded-lg bg-cyan-soft p-3"><div className="text-sm font-semibold">Apartment</div><div className="mt-1 text-xs text-cyan-strong">Location · 18 references</div></div><div className="mt-3 space-y-2">{[["Contains", "Desk · Bed · Window"], ["Appears in", "8 scenes · 27 shots"], ["Connected to", "Maya · Phone"]].map(([label, value]) => <div key={label}><div className="text-[10px] uppercase tracking-wide text-muted-foreground">{label}</div><div className="mt-1 text-xs font-medium">{value}</div></div>)}</div></InfoBlock><InfoBlock title="Relationship types"><div className="space-y-2">{["contains", "held by", "appears in", "changes state in", "located in"].map((item) => <div key={item} className="flex items-center gap-2 text-xs"><span className="h-1.5 w-1.5 rounded-full bg-cyan" />{item}</div>)}</div></InfoBlock></div></div></div>; }

function HistoryView() { const history = [["Frame generated", "Shot 04 · The Last Frame", "Today · 14:08", WandSparkles], ["Continuity issue detected", "Shot 14 · Coffee cup", "Today · 13:42", CircleDot], ["Shot approved", "Shot 03 · Scene 04", "Today · 12:20", Check], ["Prop state changed", "Phone · Scene 04", "Yesterday · 18:41", Box], ["Location analyzed", "Apartment · 18 references", "Yesterday · 16:12", ImageIcon], ["Reference added", "Maya · Side profile", "Aug 29 · 09:12", Upload]] as const; return <div><PageHeader eyebrow="Production timeline" title="History" description="A living record of how your production world evolves." action={<Button variant="outline" size="sm"><ChevronDown className="h-3.5 w-3.5" />All activity</Button>} /><div className="mb-6 flex flex-wrap gap-2">{["All", "Assets", "Scenes", "Shots", "Continuity"].map((item, index) => <Button key={item} variant={index === 0 ? "secondary" : "outline"} size="sm">{item}</Button>)}</div><div className="max-w-3xl rounded-xl border border-border bg-card p-5 sm:p-7"><div className="space-y-0">{history.map(([title, meta, time, Icon], index) => <div key={title} className="relative flex gap-4 pb-7 last:pb-0"><div className="relative flex w-8 shrink-0 justify-center"><span className={`z-10 grid h-8 w-8 place-items-center rounded-lg ${index === 0 ? "bg-cyan text-primary-foreground" : "bg-muted text-cyan-strong"}`}><Icon className="h-4 w-4" /> </span>{index < history.length - 1 && <span className="absolute top-8 h-full w-px bg-border" />}</div><div className="flex-1 pt-1"><div className="flex flex-wrap items-baseline justify-between gap-2"><div className="text-sm font-semibold">{title}</div><span className="text-[10px] text-muted-foreground">{time}</span></div><div className="mt-1 text-xs text-muted-foreground">{meta}</div></div></div>)}</div></div></div>; }

function ProductionAI({ close, go }: { close: () => void; go: (view: View) => void }) { const [message, setMessage] = useState(""); const suggestions = [["Suggest shots", Aperture, "shots"], ["Check continuity", CircleDot, "continuity"], ["Find affected scenes", Search, "scenes"], ["Explain asset state", BrainCircuit, "prop"]] as const; return <div className="fixed inset-y-0 right-0 z-40 flex w-full max-w-[390px] flex-col border-l border-border bg-background shadow-2xl"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-cyan text-primary-foreground"><Sparkles className="h-4 w-4" /></span><div><div className="text-sm font-semibold">Production AI</div><div className="text-[10px] text-muted-foreground">Home Film POC · Shot 04 context</div></div></div><Button variant="ghost" size="icon" className="h-8 w-8" onClick={close} aria-label="Close Production AI"><X className="h-4 w-4" /></Button></div><div className="flex-1 space-y-5 overflow-y-auto p-5"><div className="rounded-xl bg-cyan-soft p-4 text-sm leading-6 text-cyan-strong"><Sparkles className="mr-1 inline h-3.5 w-3.5" />I’m holding Maya, Apartment, Scene 04 and Shot 04 in context. What should we inspect?</div><div className="grid grid-cols-2 gap-2">{suggestions.map(([label, Icon, target]) => <button key={label} onClick={() => { go(target); close(); }} className="flex items-center gap-2 rounded-lg border border-border bg-card p-3 text-left text-xs font-medium hover:border-cyan/40"><Icon className="h-3.5 w-3.5 text-cyan" />{label}</button>)}</div><div className="border-t border-border pt-5"><div className="mb-3 text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Suggested insight</div><div className="rounded-xl border border-border bg-card p-4"><div className="flex gap-2"><Lightbulb className="mt-0.5 h-4 w-4 shrink-0 text-warning" /><div><div className="text-sm font-semibold">Lock the phone state</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Shot 04 inherits the active state from Scene 04. Add the phone reference before generating.</p><Button variant="link" size="sm" className="mt-2 h-auto p-0 text-xs text-cyan-strong">Apply suggestion <ArrowRight className="h-3 w-3" /></Button></div></div></div></div></div><div className="border-t border-border p-4"><div className="flex items-end gap-2 rounded-xl border border-border bg-card p-2 focus-within:border-cyan"><textarea value={message} onChange={(event) => setMessage(event.target.value)} className="min-h-10 flex-1 resize-none bg-transparent px-2 py-1 text-sm outline-none placeholder:text-muted-foreground" placeholder="Ask about this production…" rows={1} /><Button size="icon" className="h-8 w-8 bg-cyan text-primary-foreground hover:bg-cyan-strong" onClick={() => { if (message.trim()) { toast.success("Production AI is thinking", { description: "Contextual answer will appear here." }); setMessage(""); } }} aria-label="Send message"><Send className="h-3.5 w-3.5" /></Button></div><div className="mt-2 text-center text-[10px] text-muted-foreground">AI suggestions are editable and require human confirmation.</div></div></div>; }

function ProcessingOverlay({ label }: { label: string }) { const stages = ["Preparing production context", "Checking references", label, "Validating continuity"]; return <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/30 p-5 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl border border-border bg-card p-7 shadow-xl"><div className="mb-6 flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-cyan text-primary-foreground ai-pulse"><Sparkles className="h-5 w-5" /></span><div><div className="text-base font-semibold">{label}</div><div className="text-xs text-muted-foreground">Working inside Home Film POC</div></div></div><div className="space-y-3">{stages.map((stage, index) => <div key={stage} className="flex items-center gap-3 text-sm"><span className={`grid h-5 w-5 place-items-center rounded-full ${index === 2 ? "bg-cyan text-primary-foreground" : "bg-muted text-muted-foreground"}`}>{index === 2 ? <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary-foreground" /> : index < 2 ? <Check className="h-3 w-3 text-success" /> : <span className="h-1.5 w-1.5 rounded-full bg-border" />}</span><span className={index === 2 ? "font-medium" : "text-muted-foreground"}>{stage}{index === 2 && <span className="ml-1 inline-flex gap-0.5"><span className="animate-bounce">.</span><span className="animate-bounce [animation-delay:100ms]">.</span><span className="animate-bounce [animation-delay:200ms]">.</span></span>}</span></div>)}</div><div className="mt-6 border-t border-border pt-4 text-[10px] text-muted-foreground">No precise percentage. FRAMEFLOW advances when each stage is ready.</div></div></div>; }

function CommandPalette({ open, close, go, onCreate }: { open: boolean; close: () => void; go: (view: View) => void; onCreate: () => void }) { const commands: [string, string, View | "create", typeof Compass][] = [["Go to Overview", "Navigate", "overview", Compass], ["Go to Projects", "Navigate", "projects", FolderOpen], ["Go to Characters", "Navigate", "characters", Users], ["Go to Locations", "Navigate", "locations", MapPin], ["Go to Stories", "Navigate", "stories", Lightbulb], ["Go to Scenes", "Navigate", "scenes", Clapperboard], ["Go to Shots", "Navigate", "shots", Target], ["Go to Storyboard", "Navigate", "storyboard", Film], ["Go to Continuity", "Navigate", "continuity", CircleDot], ["Create new project", "Create", "create", Plus]]; return <Dialog open={open} onOpenChange={(value) => !value && close()}><DialogContent className="top-[20%] max-w-xl translate-y-0 overflow-hidden p-0"><DialogHeader className="sr-only"><DialogTitle>Command palette</DialogTitle><DialogDescription>Navigate FRAMEFLOW</DialogDescription></DialogHeader><div className="flex items-center gap-3 border-b border-border px-4"><Search className="h-5 w-5 text-muted-foreground" /><input autoFocus placeholder="Search commands or production…" className="h-14 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground" /><kbd className="rounded border border-border px-1.5 py-0.5 text-[10px] text-muted-foreground">ESC</kbd></div><div className="max-h-[420px] overflow-y-auto p-2">{commands.map(([label, meta, target, Icon]) => <button key={label} onClick={() => target === "create" ? onCreate() : (go(target), close())} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-accent"><span className="grid h-8 w-8 place-items-center rounded-md bg-muted text-cyan-strong"><Icon className="h-4 w-4" /></span><span className="flex-1 text-sm font-medium">{label}</span><span className="text-[10px] text-muted-foreground">{meta}</span><ArrowRight className="h-3.5 w-3.5 text-muted-foreground" /></button>)}</div><div className="flex items-center gap-4 border-t border-border px-4 py-3 text-[10px] text-muted-foreground"><span><kbd className="mr-1 rounded border border-border px-1">↑↓</kbd>Navigate</span><span><kbd className="mr-1 rounded border border-border px-1">↵</kbd>Open</span><span><kbd className="mr-1 rounded border border-border px-1">esc</kbd>Close</span></div></DialogContent></Dialog>; }

function CreateProject({ open, close, go }: { open: boolean; close: () => void; go: (view: View) => void }) { const [step, setStep] = useState(1); return <Dialog open={open} onOpenChange={(value) => !value && close()}><DialogContent className="max-w-lg"><DialogHeader><div className="mb-2 flex items-center gap-2 text-xs text-cyan-strong"><span className="h-1.5 w-1.5 rounded-full bg-cyan" />New production</div><DialogTitle>{step === 1 ? "Create your production" : step === 2 ? "Set up your world" : "Your production is ready"}</DialogTitle><DialogDescription>{step === 1 ? "Start with a name and a little context." : step === 2 ? "FRAMEFLOW can shape the first production context from these starting points." : "Home Film POC has been added to your workspace."}</DialogDescription></DialogHeader>{step === 1 && <div className="space-y-4 py-3"><label className="block text-xs font-medium">Project name<input defaultValue="Home Film POC" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-cyan" /></label><label className="block text-xs font-medium">Description<textarea defaultValue="A quiet apartment. A missing hour. Three people who remember it differently." className="mt-2 min-h-24 w-full resize-none rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none focus:border-cyan" /></label><div className="rounded-xl border border-dashed border-border bg-muted p-5 text-center"><Upload className="mx-auto h-5 w-5 text-cyan" /><div className="mt-2 text-sm font-medium">Add a cover image</div><div className="mt-1 text-xs text-muted-foreground">Optional · original preserved</div></div></div>}{step === 2 && <div className="space-y-3 py-3">{[["Characters", "Maya, Daniel", Users], ["Locations", "Apartment, Rooftop", MapPin], ["Props", "Phone, Coffee cup, Camera", Box]].map(([label, value, Icon]) => <div key={label} className="flex items-center gap-3 rounded-xl border border-border bg-card p-3"><span className="grid h-9 w-9 place-items-center rounded-lg bg-cyan-soft text-cyan"><Icon className="h-4 w-4" /></span><span className="flex-1"><span className="block text-sm font-semibold">{label}</span><span className="block text-xs text-muted-foreground">{value}</span></span><Check className="h-4 w-4 text-success" /></div>)}</div>}{step === 3 && <div className="py-4 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-success/15 text-success"><Check className="h-7 w-7" /></div><p className="mt-4 text-sm text-muted-foreground">Your production world has been seeded with demo context so you can start exploring immediately.</p></div>}<DialogFooter><Button variant="outline" onClick={() => step === 1 ? close() : setStep(step - 1)}>{step === 1 ? "Cancel" : "Back"}</Button><Button onClick={() => step < 3 ? setStep(step + 1) : (close(), go("project"))} className="bg-cyan text-primary-foreground hover:bg-cyan-strong">{step === 1 ? "Continue" : step === 2 ? "Create project" : "Open project"}<ArrowRight className="h-4 w-4" /></Button></DialogFooter></DialogContent></Dialog>; }

function CreateAsset({ open, close, go }: { open: boolean; close: () => void; go: (view: View) => void }) { const [step, setStep] = useState(1); return <Dialog open={open} onOpenChange={(value) => !value && close()}><DialogContent className="max-w-lg"><DialogHeader><div className="mb-2 flex items-center gap-2 text-xs text-cyan-strong"><span className="h-1.5 w-1.5 rounded-full bg-cyan" />Asset ingestion · Step {step} of 3</div><DialogTitle>{step === 1 ? "What are you creating?" : step === 2 ? "Add production references" : "Review AI suggestions"}</DialogTitle><DialogDescription>{step === 1 ? "Choose the asset type so FRAMEFLOW knows how to structure context." : step === 2 ? "Originals stay preserved while thumbnails and metadata are prepared." : "Nothing is silently accepted. Confirm what belongs in your production world."}</DialogDescription></DialogHeader>{step === 1 && <div className="grid grid-cols-2 gap-3 py-3">{[["Character", Users], ["Location", MapPin], ["Room", Box], ["Prop", Archive], ["Wardrobe", BriefcaseBusiness], ["Vehicle", Activity]].map(([label, Icon]) => <button key={label} onClick={() => setStep(2)} className="flex items-center gap-3 rounded-xl border border-border p-4 text-left transition-colors hover:border-cyan hover:bg-cyan-soft"><Icon className="h-4 w-4 text-cyan" /><span className="text-sm font-medium">{label}</span><ChevronRight className="ml-auto h-4 w-4 text-muted-foreground" /></button>)}</div>}{step === 2 && <div className="space-y-4 py-3"><label className="block text-xs font-medium">Asset name<input defaultValue="Coffee Cup" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-cyan" /></label><div className="rounded-xl border border-dashed border-cyan/50 bg-cyan-soft/50 p-8 text-center"><Upload className="mx-auto h-7 w-7 text-cyan" /><div className="mt-3 text-sm font-semibold">Drop production references here</div><div className="mt-1 text-xs text-muted-foreground">or <span className="font-medium text-cyan-strong">upload images</span></div><div className="mt-5 flex justify-center gap-2"><Badge className="bg-card text-muted-foreground">Original preserved</Badge><Badge className="bg-card text-muted-foreground">AI analysis queued</Badge></div></div></div>}{step === 3 && <div className="space-y-3 py-3">{[["Possible object", "Coffee cup", "High", "Confirm"], ["Location", "Apartment / Desk", "High", "Confirm"], ["Condition", "Intact", "Medium", "Edit"]].map(([label, value, confidence, action]) => <div key={label} className="rounded-xl border border-border p-4"><div className="flex items-start justify-between"><div><div className="text-[10px] uppercase tracking-wide text-muted-foreground">AI Suggested</div><div className="mt-1 text-sm font-semibold">{label}: {value}</div></div><Badge variant="secondary" className={confidence === "High" ? "bg-success/15 text-success" : "bg-warning/15 text-warning"}>{confidence} confidence</Badge></div><div className="mt-3 flex gap-2"><Button size="sm" className="h-7 bg-cyan text-primary-foreground hover:bg-cyan-strong"><Check className="h-3 w-3" />{action}</Button><Button variant="outline" size="sm" className="h-7">Reject</Button></div></div>)}</div>}<DialogFooter><Button variant="outline" onClick={() => step === 1 ? close() : setStep(step - 1)}>{step === 1 ? "Cancel" : "Back"}</Button>{step > 1 && <Button onClick={() => step === 2 ? setStep(3) : (close(), go("prop"))} className="bg-cyan text-primary-foreground hover:bg-cyan-strong">{step === 2 ? "Analyze references" : "Create asset"}<ArrowRight className="h-4 w-4" /></Button>}</DialogFooter></DialogContent></Dialog>; }